import{_ as e,o,c as r,a2 as s}from"./chunks/framework.CqdVOxXJ.js";const p=JSON.parse('{"title":"5. Lane 1 — Private / walk-in jobs","description":"","frontmatter":{},"headers":[],"relativePath":"chapters/05-lane-1-private-walk-in-jobs.md","filePath":"chapters/05-lane-1-private-walk-in-jobs.md","lastUpdated":null}'),n={name:"chapters/05-lane-1-private-walk-in-jobs.md"};function a(i,t,l,d,g,c){return o(),r("div",null,[...t[0]||(t[0]=[s('<h1 id="_5-lane-1-—-private-walk-in-jobs" tabindex="-1">5. Lane 1 — Private / walk-in jobs <a class="header-anchor" href="#_5-lane-1-—-private-walk-in-jobs" aria-label="Permalink to &quot;5. Lane 1 — Private / walk-in jobs&quot;">​</a></h1><p><strong>For:</strong> Shop Owner · <strong>Hubs:</strong> Workshop, Finance · <strong>Nature:</strong> Private · <strong>Job type:</strong> Retail</p><p>This is the base flow every other lane builds on. A private customer drives in (or calls, messages, books online), you quote, collect a down payment, repair, invoice, collect the balance and release.</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>Intake forms → New job (Booked) → Quote → Customer approves → Down payment</span></span>\n<span class="line"><span>→ Assign technician → Under repair → Quality check → Ready for pickup</span></span>\n<span class="line"><span>→ Customer invoice → Final payment → Release checklist → Released → Closed</span></span></code></pre></div><h2 id="status-map" tabindex="-1">Status map <a class="header-anchor" href="#status-map" aria-label="Permalink to &quot;Status map {#status-map}&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Status</th><th>Meaning</th><th>Main next step (button)</th></tr></thead><tbody><tr><td><strong>New inquiry</strong></td><td>Lead from web, Messenger or the sales pipeline</td><td><strong>Confirm booking</strong></td></tr><tr><td><strong>Booked</strong></td><td>Car or appointment confirmed</td><td><strong>Mark quoted</strong> / <strong>For canvass</strong> / <strong>Start work</strong></td></tr><tr><td><strong>For canvass</strong></td><td>Parts prices being gathered</td><td><strong>Mark quoted</strong></td></tr><tr><td><strong>Quoted</strong></td><td>Estimate given</td><td><strong>Start work</strong></td></tr><tr><td><strong>Waiting for LOA</strong> / <strong>Authorized</strong></td><td>Insurance only (<a href="/rakkii-cars-guide/chapters/06-lane-2-insurance-claims-and-loa">Chapter 6</a>)</td><td><strong>Mark authorized</strong> → <strong>Start work</strong></td></tr><tr><td><strong>Under repair</strong></td><td>In the bay</td><td><strong>Ready for pickup</strong> or <strong>Send to QC</strong></td></tr><tr><td><strong>Waiting for parts</strong></td><td>Paused for an ordered part</td><td><strong>Parts in — back to shop</strong></td></tr><tr><td><strong>Quality check</strong></td><td>Being inspected</td><td><strong>Ready for pickup</strong> / <strong>Back to shop</strong></td></tr><tr><td><strong>On hold</strong></td><td>Paused with a reason</td><td><strong>Resume</strong> / <strong>Cancel job</strong></td></tr><tr><td><strong>Ready for pickup</strong></td><td>Done, waiting for the customer</td><td><strong>Release car</strong></td></tr><tr><td><strong>Released</strong></td><td>Car has left</td><td><strong>Close job</strong> (or <strong>Mark invoiced</strong>)</td></tr><tr><td><strong>Invoiced</strong></td><td>Optional bookkeeping step after release</td><td><strong>Close job</strong></td></tr><tr><td><strong>Closed</strong></td><td>Finished</td><td>—</td></tr><tr><td><strong>Cancelled</strong> / <strong>No-show</strong></td><td>Ended without work (reason required to cancel)</td><td>—</td></tr></tbody></table><p>Every status change is kept in the job&#39;s <strong>Status log</strong> with who moved it and when.</p><h2 id="_5-1-before-the-car-is-touched-intake-paperwork" tabindex="-1">5.1 Before the car is touched: intake paperwork <a class="header-anchor" href="#_5-1-before-the-car-is-touched-intake-paperwork" aria-label="Permalink to &quot;5.1 Before the car is touched: intake paperwork&quot;">​</a></h2><h3 id="undertaking-vehicle-intake-checklist-workshop-forms-intake" tabindex="-1">Undertaking &amp; Vehicle intake checklist (<code>/workshop/forms/intake</code>) <a class="header-anchor" href="#undertaking-vehicle-intake-checklist-workshop-forms-intake" aria-label="Permalink to &quot;Undertaking &amp; Vehicle intake checklist (`/workshop/forms/intake`)&quot;">​</a></h3><ol><li>Go to <strong>Workshop › Forms</strong> and on <strong>Undertaking and vehicle intake checklist</strong> press <strong>Start from job</strong> (after the job exists) or <strong>Open</strong> for a blank.</li><li>Fill the undertaking blanks (date, owner name, make/model, plate). The wording itself is fixed.</li><li>On the <strong>Vehicle intake checklist</strong>: customer, address, date, color, model/unit, odometer, plate; <strong>tap each damaged panel</strong>; set <strong>Fuel level</strong>; mark each item <strong>Present / Not present</strong>; add <strong>Remarks</strong>.</li><li>Press <strong>Save on job</strong> (when started from a job), then <strong>Print</strong> for signatures (customer, inspected by).</li></ol><h3 id="vehicle-pick-up-delivery-waiver-workshop-forms-vd-waiver" tabindex="-1">Vehicle Pick-up &amp; Delivery Waiver (<code>/workshop/forms/vd-waiver</code>) <a class="header-anchor" href="#vehicle-pick-up-delivery-waiver-workshop-forms-vd-waiver" aria-label="Permalink to &quot;Vehicle Pick-up &amp; Delivery Waiver (`/workshop/forms/vd-waiver`)&quot;">​</a></h3><p>Use it when a driver picks up or delivers the customer&#39;s car outside the shop. It covers customer and vehicle information, pickup/delivery addresses and times, a pre-delivery damage diagram, condition checks, terms and signatures. Fill it, then <strong>Print</strong>. It is also on the job&#39;s Quote and Work tabs as <strong>Pickup/Delivery waiver</strong>.</p><div class="info custom-block"><p class="custom-block-title">📷 Screenshot placeholder</p><p><code>/screenshots/05-lane-1-private-walk-in-jobs/01-intake-checklist.png</code> — Vehicle intake checklist with car panel diagram.</p></div><h2 id="_5-2-create-the-job-workshop-jobs-new" tabindex="-1">5.2 Create the job (<code>/workshop/jobs/new</code>) <a class="header-anchor" href="#_5-2-create-the-job-workshop-jobs-new" aria-label="Permalink to &quot;5.2 Create the job (`/workshop/jobs/new`)&quot;">​</a></h2><ol><li>Press <strong>New job</strong> (Workshop pin).</li><li><strong>How the job came in</strong><ul><li><strong>How they arrived</strong>: Walk-in, Phone, Messenger, Website or Sales.</li><li><strong>Job type</strong>: Retail. <strong>Nature</strong>: Private. <strong>Tax</strong>: VAT or Non-VAT (shop default pre-selected).</li><li><strong>Sales advisor</strong> (optional, never earns commission) and <strong>Referred by (staff)</strong> (optional, earns in-house commission unless the channel is a no-commission channel).</li><li><strong>Agent fee (₱)</strong> only if an outside agent referred the customer; a <strong>Fee reason</strong> is needed when it differs from the shop default.</li></ul></li><li><strong>Customer</strong> — type two letters of the <strong>Customer name</strong> to find someone on file, or enter a new <strong>Name</strong>, <strong>Mobile</strong> (required), <strong>Email</strong> and <strong>Customer category</strong> (Person).</li><li><strong>Vehicle</strong> — <strong>Plate</strong> (required), <strong>Make</strong>, <strong>Model</strong>, <strong>Year</strong>.</li><li><strong>Work</strong> — <strong>Work category</strong>, <strong>Promised date</strong>, <strong>Services</strong> and <strong>Notes</strong>.</li><li>Press <strong>Create job</strong>. A desk-created job starts at <strong>Booked</strong> and gets a job reference and a customer pay link.</li></ol><h2 id="_5-3-build-the-quote" tabindex="-1">5.3 Build the quote <a class="header-anchor" href="#_5-3-build-the-quote" aria-label="Permalink to &quot;5.3 Build the quote&quot;">​</a></h2><h3 id="work-lines-work-tab" tabindex="-1">Work lines (Work tab) <a class="header-anchor" href="#work-lines-work-tab" aria-label="Permalink to &quot;Work lines (Work tab)&quot;">​</a></h3><ol><li>Open the job&#39;s <strong>Work</strong> tab, card <strong>Work lines</strong>.</li><li>For each line choose <strong>Kind</strong> (Labor, Part, Paint, Fee, Other). For parts pick a <strong>Catalog part</strong> (shows on hand and low stock) or <strong>One-off instead</strong>.</li><li>Enter <strong>Description</strong>, <strong>Qty</strong>, <strong>Cost</strong> (what it costs the shop) and <strong>Sell</strong> (customer price). <strong>Who pays</strong> = Customer.</li><li><strong>Add line</strong>. Untick or remove lines the customer did not approve.</li></ol><p>If the parts need supplier prices first, tick <strong>Needs canvass</strong> / <strong>Needs parts buy</strong> on <strong>Overview</strong> (retail jobs can skip both) and see <a href="/rakkii-cars-guide/chapters/09-parts-inventory-canvass-restock-payables">Chapter 9</a>.</p><h3 id="customer-estimate-and-margin-warning-quote-tab" tabindex="-1">Customer estimate and margin warning (Quote tab) <a class="header-anchor" href="#customer-estimate-and-margin-warning-quote-tab" aria-label="Permalink to &quot;Customer estimate and margin warning (Quote tab)&quot;">​</a></h3><ol><li>Open the <strong>Quote</strong> tab. The <strong>Customer estimate</strong> shows sell prices only.</li><li>Check the margin. If it is under the shop&#39;s minimum (30% by default) you see &quot;Margin X% is under the 30% floor.&quot; <ul><li>In <strong>Warn</strong> mode you can still save; the job is flagged.</li><li>In <strong>Block</strong> mode the owner (or admin) must type an <strong>Override reason</strong> to save.</li></ul></li><li>Press <strong>Create quote</strong>. The status becomes <strong>Quoted</strong> (or press <strong>Mark quoted</strong>).</li><li><strong>Print estimate</strong> for a paper copy.</li></ol><h2 id="_5-4-customer-approval-through-the-customer-portal" tabindex="-1">5.4 Customer approval through the Customer Portal <a class="header-anchor" href="#_5-4-customer-approval-through-the-customer-portal" aria-label="Permalink to &quot;5.4 Customer approval through the Customer Portal&quot;">​</a></h2><ol><li>On the Quote tab press <strong>Copy customer link</strong> and send it by SMS, Messenger or email.</li><li>The customer opens the pay link on the Customer Portal (for example <code>https://rakkii-web-int.web.app/pay/&lt;token&gt;</code>). They see the job, plate, estimate total and <strong>Your share (Balance due)</strong>.</li><li>They press <strong>Approve estimate</strong> or <strong>Decline estimate</strong>. Approving or declining takes no payment.</li><li>Back in Ops the Quote tab shows &quot;Last quote: … · Approved by … · date&quot;.</li></ol><p>The same page lets the customer <strong>Upload payment screenshot</strong> for GCash or Maya. Those arrive in <strong>Finance › Payments › Pending proofs</strong> for you to confirm (<a href="/rakkii-cars-guide/chapters/08-lane-4-billing-chain-receivables-storage-credit-notes">Chapter 8</a>).</p><div class="info custom-block"><p class="custom-block-title">📷 Screenshot placeholder</p><p><code>/screenshots/05-lane-1-private-walk-in-jobs/02-portal-approve.png</code> — Customer Portal pay page with Approve estimate / Decline estimate.</p></div><h2 id="_5-5-record-the-50-down-payment" tabindex="-1">5.5 Record the 50% down payment <a class="header-anchor" href="#_5-5-record-the-50-down-payment" aria-label="Permalink to &quot;5.5 Record the 50% down payment&quot;">​</a></h2><p>The <strong>Pay › Money</strong> card shows <strong>Customer owes</strong>, <strong>Cash in</strong>, <strong>DP required</strong>, <strong>DP collected</strong> and <strong>DP still due</strong>. Private jobs default to <strong>50%</strong> of the customer share.</p><ol><li>Open <strong>Pay › Record a payment</strong>.</li><li><strong>Who paid</strong>: Customer. <strong>Amount</strong>: the down payment. <strong>Method</strong>: Cash, GCash, Maya, Bank transfer, Card or Other.</li><li>For bank transfers pick the <strong>Bank account</strong> code, and fill <strong>Particular</strong> (often the plate) and <strong>Reference</strong>.</li><li>Optionally set <strong>Deposited to</strong> (which shop account the money went into).</li><li>Press <strong>Record payment</strong>, then <strong>Print acknowledgement</strong> for the customer.</li></ol><p><strong>Down payment rules</strong></p><ul><li>The owner decides per nature whether the deposit blocks anything: <strong>Does not block</strong> (default), <strong>Before work</strong> or <strong>Before release</strong> (Chapter 13).</li><li>To change one job, use <strong>Percent override</strong> or <strong>Amount override</strong> with a <strong>Reason</strong>, then <strong>Save down payment</strong>.</li><li>If the deposit blocks work and you must start anyway, the owner (or admin) enters a <strong>Bypass reason to start work without the deposit</strong>.</li></ul><h2 id="_5-6-assign-the-technician-and-start-work" tabindex="-1">5.6 Assign the technician and start work <a class="header-anchor" href="#_5-6-assign-the-technician-and-start-work" aria-label="Permalink to &quot;5.6 Assign the technician and start work&quot;">​</a></h2><ol><li><strong>Work › Technicians and dates</strong>: pick the technician(s), choose a <strong>Reason for change</strong>, press <strong>Save technicians</strong>. Changes are kept in <strong>Assignment history</strong>.</li><li>Set <strong>Start</strong> and <strong>Car in</strong> dates and <strong>Save dates</strong>.</li><li>Apply a <strong>Bay checklist</strong> template (<strong>Template › Apply template</strong>) so the technician has steps to tick.</li><li>Press <strong>Start work</strong>. Status: <strong>Under repair</strong>.</li></ol><h2 id="_5-7-bay-checklist-and-qc-photos" tabindex="-1">5.7 Bay checklist and QC photos <a class="header-anchor" href="#_5-7-bay-checklist-and-qc-photos" aria-label="Permalink to &quot;5.7 Bay checklist and QC photos&quot;">​</a></h2><p>The technician ticks the <strong>Bay checklist</strong> and uploads the four <strong>QC photos</strong> — <strong>Front</strong>, <strong>Rear</strong>, <strong>Left side (LS)</strong>, <strong>Right side (RS)</strong> (<a href="/rakkii-cars-guide/chapters/02-technician-daily-guide#_2-8-uploading-the-four-qc-photos">Chapter 2</a>).</p><ol><li>When work is done, press <strong>Send to QC</strong> (optional inspection step) or go straight to <strong>Ready for pickup</strong>.</li><li>The app refuses <strong>Ready for pickup</strong> until the QC photo count is met (&quot;QC photos: 4/4&quot;).</li><li>If photos truly cannot be taken, the owner types a <strong>QC override reason</strong> and <strong>Save QC override</strong>.</li><li>Print the <strong>QC summary</strong> if the customer wants it.</li></ol><h2 id="_5-8-create-and-post-the-customer-invoice" tabindex="-1">5.8 Create and post the customer invoice <a class="header-anchor" href="#_5-8-create-and-post-the-customer-invoice" aria-label="Permalink to &quot;5.8 Create and post the customer invoice&quot;">​</a></h2><ol><li>Open <strong>Pay › Invoices</strong>. The app offers <strong>Bill customer ₱…</strong> based on the approved customer lines.</li><li>Press it. The invoice is created <strong>Posted</strong>, with a number from the VAT or Non-VAT series.</li><li>Press <strong>Print customer invoice</strong>. <strong>Print payment instructions</strong> gives the customer the pay link, GCash/Maya and bank details.</li></ol><p>Posting an invoice does not change the job status.</p><h2 id="_5-9-record-the-final-balance" tabindex="-1">5.9 Record the final balance <a class="header-anchor" href="#_5-9-record-the-final-balance" aria-label="Permalink to &quot;5.9 Record the final balance&quot;">​</a></h2><ol><li><strong>Pay › Record a payment</strong>, <strong>Who paid</strong>: Customer.</li><li>Press <strong>Fill customer balance</strong> to enter exactly what is left, pick the <strong>Method</strong>, and <strong>Apply to invoice</strong>.</li><li><strong>Record payment</strong>. <strong>Customer owes</strong> should read PHP 0.00.</li></ol><p>By default the car is held until the customer balance is zero (&quot;Hold the car until the customer has paid: Yes&quot; on Overview).</p><h2 id="_5-10-release-checklist-gate-pass-and-acceptance" tabindex="-1">5.10 Release checklist, gate pass and acceptance <a class="header-anchor" href="#_5-10-release-checklist-gate-pass-and-acceptance" aria-label="Permalink to &quot;5.10 Release checklist, gate pass and acceptance&quot;">​</a></h2><ol><li>Open the <strong>Release</strong> tab. If the job is not yet <strong>Ready for pickup</strong> it says &quot;Move the job to Ready for pickup first.&quot;</li><li>Print the <strong>Acceptance</strong> (acceptance and satisfaction of repair) and have the customer sign it. Print the <strong>Gate pass</strong> for the guard.</li><li>Tick the three release checks: <ul><li><strong>Keys logged</strong></li><li><strong>Documents in / out</strong></li><li><strong>Customer signed release</strong></li></ul></li><li>Press <strong>Release car</strong>. The job becomes <strong>Released</strong> and records who released it and when.</li></ol><div class="tip custom-block"><p class="custom-block-title">Rakkii&#39;s hand-over routine</p><p>Before ticking <strong>Customer signed release</strong>, confirm the shop&#39;s hand-over steps: the customer signed the acceptance form, the old replaced parts were returned to the customer, and the car was washed and vacuumed. Add these as steps in a &quot;Release prep&quot; bay checklist template (Admin › Shop settings › Company › Lists › Checklist templates) so they are ticked and logged on every job.</p></div><p><strong>What blocks release (and who can pass it)</strong></p><table tabindex="0"><thead><tr><th>Block</th><th>Message</th><th>Way through</th></tr></thead><tbody><tr><td>Not Ready</td><td>&quot;Job must be in ready status before release.&quot;</td><td>Finish QC, mark Ready</td></tr><tr><td>Customer balance open</td><td>&quot;Customer still owes. Default is to hold the car.&quot;</td><td>Collect, or <strong>Owner override</strong> + reason</td></tr><tr><td>Down payment before release</td><td>&quot;Down payment shortfall … still due before release.&quot;</td><td>Collect, or owner override</td></tr><tr><td>QC photos missing</td><td>names the missing angle</td><td>Upload, or QC override reason</td></tr><tr><td>Release checks not ticked</td><td>&quot;Keys logged, documents in/out and customer signed must all be ticked…&quot;</td><td>Tick, or owner override + reason</td></tr><tr><td>Invoices not posted (if the job holds for invoices)</td><td>&quot;Post the customer invoice before release.&quot;</td><td>Post, or owner reason &quot;Reason to release before invoices are posted&quot;</td></tr></tbody></table><div class="info custom-block"><p class="custom-block-title">📷 Screenshot placeholder</p><p><code>/screenshots/05-lane-1-private-walk-in-jobs/03-release-checklist.png</code> — Release tab with Keys logged, Documents in / out, Customer signed release.</p></div><h2 id="_5-11-close-the-job" tabindex="-1">5.11 Close the job <a class="header-anchor" href="#_5-11-close-the-job" aria-label="Permalink to &quot;5.11 Close the job&quot;">​</a></h2><ol><li>After release, press <strong>Close job</strong> (or <strong>Mark invoiced</strong> first if you track that step).</li><li>A closed job is read-only. Its car, payments and invoices stay in the customer&#39;s <strong>Service history</strong>.</li><li>Set <strong>Remind me</strong> (3, 6 or 12 months) on Overview if the customer should get a service reminder email.</li></ol>',49)])])}const u=e(n,[["render",a]]);export{p as __pageData,u as default};
